# Let's try a more sophisticated local search with tabu and restarts
import random
from collections import Counter

# Define the graph
edges = []
for clique_start in [0, 5, 10]:
    for i in range(5):
        for j in range(i+1, 5):
            edges.append((clique_start + i, clique_start + j))
for i in range(5):
    edges.append((i, 5 + i))
    edges.append((5 + i, 10 + i))

def count_conflicts(labels):
    diffs = [abs(labels[u] - labels[v]) for u, v in edges]
    c = Counter(diffs)
    conflicts = sum(max(0, count - 1) for count in c.values())
    for d in diffs:
        if d == 0 or d > 40:
            conflicts += 1
    return conflicts

def get_conflict_edges(labels):
    """Return edges that have conflicting differences"""
    diffs = {}
    conflict_edges = set()
    for idx, (u, v) in enumerate(edges):
        d = abs(labels[u] - labels[v])
        if d in diffs:
            conflict_edges.add(idx)
            conflict_edges.add(diffs[d])
        else:
            diffs[d] = idx
    return conflict_edges

def local_search_with_restarts(max_restarts=1000, max_iter_per_restart=5000):
    random.seed(456)

    for restart in range(max_restarts):
        # Random initial assignment
        labels = random.sample(range(41), 15)

        for iteration in range(max_iter_per_restart):
            conflicts = count_conflicts(labels)
            if conflicts == 0:
                return labels

            # Find vertices involved in conflicts
            conflict_edges = get_conflict_edges(labels)
            conflict_vertices = set()
            for idx in conflict_edges:
                u, v = edges[idx]
                conflict_vertices.add(u)
                conflict_vertices.add(v)

            if not conflict_vertices:
                break

            # Try swapping a conflict vertex with another vertex
            best_swap = None
            best_conflicts = conflicts

            cv_list = list(conflict_vertices)
            random.shuffle(cv_list)

            for v in cv_list[:5]:  # Try a few conflict vertices
                for other in range(15):
                    if other == v:
                        continue
                    new_labels = labels[:]
                    new_labels[v], new_labels[other] = new_labels[other], new_labels[v]
                    new_conflicts = count_conflicts(new_labels)
                    if new_conflicts < best_conflicts:
                        best_conflicts = new_conflicts
                        best_swap = (v, other, new_labels[:])

            if best_swap:
                v, other, new_labels = best_swap
                labels = new_labels
            else:
                # Try random swap
                a, b = random.sample(range(15), 2)
                labels[a], labels[b] = labels[b], labels[a]

        if restart % 100 == 0:
            print(f"Restart {restart}, best conflicts: {count_conflicts(labels)}")

    return None

result = local_search_with_restarts(500, 2000)
if result:
    print(f"Solution: {result}")
    diffs = [abs(result[u] - result[v]) for u, v in edges]
    print(f"Unique diffs: {len(set(diffs))}")
    print("VALID!")
else:
    print("No solution found")

# Let's try a SAT-based approach with a more efficient encoding
# Using minisat through pysat

from pysat.solvers import Glucose3
from pysat.card import *
import itertools

# Define the graph
edges = []
for clique_start in [0, 5, 10]:
    for i in range(5):
        for j in range(i+1, 5):
            edges.append((clique_start + i, clique_start + j))
for i in range(5):
    edges.append((i, 5 + i))
    edges.append((5 + i, 10 + i))

print(f"Edges: {len(edges)}")

# Encoding: 
# x[v][l] = True if vertex v has label l
# y[e][d] = True if edge e has difference d

# Variables:
# x[v][l] for v in 0..14, l in 0..40: 15*41 = 615 vars
# y[e][d] for e in 0..39, d in 1..40: 40*40 = 1600 vars
# Total: ~2215 vars

def var_x(v, l):
    return v * 41 + l + 1  # 1-indexed

def var_y(e, d):
    return 15 * 41 + e * 40 + d  # 1-indexed

solver = Glucose3()

# Each vertex gets exactly one label
for v in range(15):
    # At least one
    solver.add_clause([var_x(v, l) for l in range(41)])
    # At most one
    for l1 in range(41):
        for l2 in range(l1+1, 41):
            solver.add_clause([-var_x(v, l1), -var_x(v, l2)])

# Each label used at most once
for l in range(41):
    for v1 in range(15):
        for v2 in range(v1+1, 15):
            solver.add_clause([-var_x(v1, l), -var_x(v2, l)])

# Edge difference constraints
for e, (u, v) in enumerate(edges):
    for l1 in range(41):
        for l2 in range(41):
            if l1 == l2:
                continue
            d = abs(l1 - l2)
            if d < 1 or d > 40:
                continue
            # If vertex u has label l1 and vertex v has label l2, then edge e has difference d
            solver.add_clause([-var_x(u, l1), -var_x(v, l2), var_y(e, d)])

# Each edge has exactly one difference
for e in range(40):
    solver.add_clause([var_y(e, d) for d in range(1, 41)])
    for d1 in range(1, 41):
        for d2 in range(d1+1, 41):
            solver.add_clause([-var_y(e, d1), -var_y(e, d2)])

# Each difference used at most once
for d in range(1, 41):
    for e1 in range(40):
        for e2 in range(e1+1, 40):
            solver.add_clause([-var_y(e1, d), -var_y(e2, d)])

print("Encoding complete, solving...")
import time
start = time.time()
if solver.solve():
    model = solver.get_model()
    print(f"Solved in {time.time()-start:.2f}s")

    # Extract solution
    labels = [0] * 15
    for lit in model:
        if lit > 0 and lit <= 15 * 41:
            v = (lit - 1) // 41
            l = (lit - 1) % 41
            labels[v] = l

    print(f"Labels: {labels}")

    # Verify
    diffs = [abs(labels[u] - labels[v]) for u, v in edges]
    print(f"Unique diffs: {len(set(diffs))}")
    if len(set(diffs)) == 40:
        print("VALID!")
else:
    print(f"UNSAT in {time.time()-start:.2f}s")
